## 三、断点续问实现

### 3.1 数据模型

```typescript
/**
 * src/models/Session.ts
 * 
 * 会话数据模型
 * 
 * 功能：
 * - 定义会话的数据结构
 * - 存储对话历史消息
 * - 支持会话的元数据和归档
 * 
 * 字段说明：
 * - sessionId: 会话唯一标识
 * - userId: 用户 ID
 * - messages: 对话消息数组
 * - metadata: 会话元数据（可选）
 * - createdAt: 创建时间
 * - updatedAt: 更新时间
 * - lastActivityAt: 最后活动时间
 * - isArchived: 是否已归档
 */

import mongoose, { Document, Schema } from 'mongoose';

/**
 * 消息接口
 * 
 * 定义对话消息的基本结构
 */
export interface IMessage {
  /** 消息角色：user/assistant/system */
  role: 'user' | 'assistant' | 'system';
  /** 消息内容 */
  content: string;
  /** 消息消耗的 Token 数量（可选） */
  tokens?: number;
  /** 消息元数据（可选） */
  metadata?: Record<string, any>;
  /** 消息时间戳 */
  timestamp: Date;
}

/**
 * 会话文档接口
 * 
 * 定义会话的完整数据结构
 */
export interface ISession extends Document {
  /** 会话唯一标识 */
  sessionId: string;
  /** 用户 ID */
  userId: string;
  /** 对话消息数组 */
  messages: IMessage[];
  /** 会话元数据（可选） */
  metadata?: Record<string, any>;
  /** 创建时间 */
  createdAt: Date;
  /** 更新时间 */
  updatedAt: Date;
  /** 最后活动时间 */
  lastActivityAt: Date;
  /** 是否已归档 */
  isArchived: boolean;
}

/**
 * 消息 Schema
 * 
 * 定义消息的数据结构和验证规则
 */
const MessageSchema: Schema = new Schema({
  // 消息角色，必须是 user/assistant/system 之一
  role: {
    type: String,
    enum: ['user', 'assistant', 'system'],
    required: true
  },
  // 消息内容，必填
  content: {
    type: String,
    required: true
  },
  // Token 消耗量（可选）
  tokens: Number,
  // 元数据，使用 Map 类型存储键值对
  metadata: {
    type: Map,
    of: Schema.Types.Mixed
  },
  // 时间戳，默认为当前时间
  timestamp: {
    type: Date,
    default: Date.now
  }
});

/**
 * 会话 Schema
 * 
 * 定义会话的数据结构和验证规则
 */
const SessionSchema: Schema = new Schema({
  // 会话 ID，唯一索引
  sessionId: {
    type: String,
    required: true,
    unique: true,
    index: true
  },
  // 用户 ID，建立索引以加速查询
  userId: {
    type: String,
    required: true,
    index: true
  },
  // 消息数组
  messages: [MessageSchema],
  // 元数据
  metadata: {
    type: Map,
    of: Schema.Types.Mixed
  },
  // 创建时间
  createdAt: {
    type: Date,
    default: Date.now
  },
  // 更新时间
  updatedAt: {
    type: Date,
    default: Date.now
  },
  // 最后活动时间，用于排序和清理
  lastActivityAt: {
    type: Date,
    default: Date.now
  },
  // 归档标记
  isArchived: {
    type: Boolean,
    default: false
  }
});

/**
 * 更新时间中间件
 * 
 * 在每次保存前自动更新 updatedAt 字段
 */
SessionSchema.pre('save', function(next) {
  this.updatedAt = new Date();
  next();
});

/**
 * 复合索引
 * 
 * 创建复合索引以优化常见查询
 */
SessionSchema.index({ userId: 1, lastActivityAt: -1 });
SessionSchema.index({ userId: 1, isArchived: 1 });

/**
 * 导出 Session 模型
 * 
 * @example
 * const session = new Session({
 *   sessionId: 'session-123',
 *   userId: 'user-456',
 *   messages: [...]
 * });
 * await session.save();
 */
export default mongoose.model<ISession>('Session', SessionSchema);
```

