## 一、任务模型

```typescript
/**
 * src/models/Task.ts
 * 
 * 任务数据模型
 * 
 * 功能：
 * - 定义任务的数据结构
 * - 支持任务状态跟踪（PENDING/PROCESSING/COMPLETED/FAILED/CANCELLED）
 * - 支持优先级调度（URGENT/HIGH/NORMAL/LOW）
 * - 支持重试机制
 * - 支持进度追踪
 * 
 * 字段说明：
 * - taskId: 任务唯一标识
 * - userId: 用户 ID
 * - sessionId: 关联的会话 ID（可选）
 * - type: 任务类型（chat/code-generation/document-summary/data-analysis）
 * - status: 任务状态
 * - priority: 任务优先级
 * - input: 任务输入数据
 * - output: 任务输出结果
 * - error: 错误信息（如果有）
 * - progress: 进度（0-100）
 * - retryCount: 重试次数
 * - maxRetries: 最大重试次数
 */

import mongoose, { Document, Schema } from 'mongoose';

/**
 * 任务状态枚举
 * 
 * 定义任务的生命周期状态
 */
export enum TaskStatus {
  /** 等待执行 */
  PENDING = 'pending',
  /** 正在执行 */
  PROCESSING = 'processing',
  /** 执行完成 */
  COMPLETED = 'completed',
  /** 执行失败 */
  FAILED = 'failed',
  /** 已取消 */
  CANCELLED = 'cancelled'
}

/**
 * 任务优先级枚举
 * 
 * 定义任务的优先级
 */
export enum TaskPriority {
  /** 低优先级 */
  LOW = 'low',
  /** 普通优先级 */
  NORMAL = 'normal',
  /** 高优先级 */
  HIGH = 'high',
  /** 紧急优先级 */
  URGENT = 'urgent'
}

/**
 * 任务文档接口
 * 
 * 定义任务的完整数据结构
 */
export interface ITask extends Document {
  /** 任务唯一标识 */
  taskId: string;
  /** 用户 ID */
  userId: string;
  /** 关联的会话 ID（可选） */
  sessionId?: string;
  /** 任务类型 */
  type: string;
  /** 任务状态 */
  status: TaskStatus;
  /** 任务优先级 */
  priority: TaskPriority;
  /** 任务输入数据 */
  input: any;
  /** 任务输出结果 */
  output?: any;
  /** 错误信息（如果有） */
  error?: string;
  /** 进度（0-100） */
  progress: number;
  /** 元数据 */
  metadata?: Record<string, any>;
  /** 创建时间 */
  createdAt: Date;
  /** 更新时间 */
  updatedAt: Date;
  /** 开始时间 */
  startedAt?: Date;
  /** 完成时间 */
  completedAt?: Date;
  /** 重试次数 */
  retryCount: number;
  /** 最大重试次数 */
  maxRetries: number;
}

/**
 * 任务 Schema
 * 
 * 定义任务的数据结构和验证规则
 */
const TaskSchema: Schema = new Schema({
  // 任务 ID，唯一索引
  taskId: {
    type: String,
    required: true,
    unique: true,
    index: true
  },

  // 用户 ID，建立索引以加速查询
  userId: {
    type: String,
    required: true,
    index: true
  },

  // 关联的会话 ID（可选）
  sessionId: {
    type: String,
    index: true
  },

  // 任务类型
  type: {
    type: String,
    required: true,
    index: true
  },

  // 任务状态，建立索引以加速查询
  status: {
    type: String,
    enum: Object.values(TaskStatus),
    default: TaskStatus.PENDING,
    index: true
  },

  // 任务优先级
  priority: {
    type: String,
    enum: Object.values(TaskPriority),
    default: TaskPriority.NORMAL
  },

  // 任务输入数据，使用 Mixed 类型支持任意结构
  input: {
    type: Schema.Types.Mixed,
    required: true
  },

  // 任务输出结果
  output: Schema.Types.Mixed,

  // 错误信息
  error: String,

  // 进度（0-100）
  progress: {
    type: Number,
    default: 0,
    min: 0,
    max: 100
  },

  // 元数据
  metadata: {
    type: Map,
    of: Schema.Types.Mixed
  },

  // 创建时间
  createdAt: {
    type: Date,
    default: Date.now
  },

  // 更新时间
  updatedAt: {
    type: Date,
    default: Date.now
  },

  // 开始时间
  startedAt: Date,

  // 完成时间
  completedAt: Date,

  // 重试次数
  retryCount: {
    type: Number,
    default: 0
  },

  // 最大重试次数
  maxRetries: {
    type: Number,
    default: 3
  }
});

/**
 * 更新时间中间件
 * 
 * 在每次保存前自动更新 updatedAt 字段
 */
TaskSchema.pre('save', function(next) {
  this.updatedAt = new Date();
  next();
});

/**
 * 复合索引
 * 
 * 创建复合索引以优化常见查询
 */
TaskSchema.index({ userId: 1, status: 1, createdAt: -1 });
TaskSchema.index({ status: 1, priority: 1, createdAt: 1 });

/**
 * 导出 Task 模型
 * 
 * @example
 * const task = new Task({
 *   taskId: 'task-123',
 *   userId: 'user-456',
 *   type: 'chat',
 *   input: { sessionId: 'session-789', message: 'Hello' }
 * });
 * await task.save();
 */
export default mongoose.model<ITask>('Task', TaskSchema);
```

